import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPath, onModelLoaded }) => {
  const modelRef = useRef(null); // Reference for the model

  useEffect(() => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => {
        console.log('Model loaded:', obj);
        obj.scale.set(0.1, 0.1, 0.1); // Scale the model to ensure it's visible
        obj.position.set(0, 0, 0); // Ensure it's at the center
        obj.traverse((child) => {
          if (child.isMesh) {
            // Set white wireframe material
            child.material = new THREE.MeshBasicMaterial({
              color: 0xffffff, // White color for the wireframe
              wireframe: true, // Enable wireframe rendering
            });
          }
        });
        onModelLoaded(obj); // Pass the loaded model back to the parent component
      },
      undefined, // Optional progress callback
      (error) => {
        console.error('Error loading OBJ:', error); // Error handling
      }
    );
  }, [modelPath, onModelLoaded]);

  // Rotate the model slowly on each frame
  useFrame(() => {
    if (modelRef.current) {
      modelRef.current.rotation.y += 0.001; // Slow rotation speed
    }
  });

  return <primitive object={modelRef.current} />;
};

const App = () => {
  const [model, setModel] = useState(null);
  const cameraRef = useRef(); // Reference for the camera

  const modelPath = require('./stls/model.obj'); // Path to the model

  // Adjust camera based on the model size
  const adjustCameraDistance = (model) => {
    const box = new THREE.Box3().setFromObject(model); // Get the bounding box of the model
    const size = new THREE.Vector3();
    box.getSize(size); // Get the size of the model (width, height, depth)
    const center = box.getCenter(new THREE.Vector3()); // Get the center of the model

    // Calculate the camera's distance from the model based on its size
    const maxDimension = Math.max(size.x, size.y, size.z);
    const cameraDistance = maxDimension / (2 * Math.tan(Math.PI / 8)); // FOV = 75 degrees (Math.PI / 8)

    // Set the camera position
    cameraRef.current.position.set(center.x, center.y, cameraDistance * 2); // Position the camera further to ensure model fits
    cameraRef.current.lookAt(center); // Make sure the camera looks at the center of the model
  };

  useEffect(() => {
    if (model) {
      adjustCameraDistance(model); // Adjust the camera after the model is loaded
    }
  }, [model]); // Re-run this effect whenever the model is loaded

  return (
    <div style={{ height: '100vh', margin: 0 }}>
      <h1 style={{ position: 'absolute', color: 'white', top: '10px', left: '10px' }}>
        3D Model Viewer
      </h1>
      <Canvas
        style={{ backgroundColor: 'black' }} // Set the background to black
        camera={{ position: [5, 5, 5], fov: 75 }} // Initial camera setup (adjusted for 45-degree view)
      >
        {/* Lights */}
        <ambientLight intensity={0.5} /> {/* Ambient light for general lighting */}
        <spotLight position={[10, 10, 10]} intensity={1} /> {/* Spot light for more focused lighting */}
        <directionalLight position={[5, 5, 5]} intensity={1} /> {/* Directional light for strong illumination */}

        {/* Model loader */}
        {model ? (
          <primitive object={model} /> // If model is loaded, display it
        ) : (
          <ModelLoader modelPath={modelPath} onModelLoaded={setModel} /> // Load the model if not yet loaded
        )}

        {/* Orbit controls for camera movement (with no zooming) */}
        <OrbitControls enableZoom={false} />
      </Canvas>
    </div>
  );
};

export default App;
